begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select plan(12);
insert into public.calendar_event_colors(value) values ('BLUE'),('PURPLE'),('GREEN') on conflict do nothing;
insert into auth.users(id) values ('00000000-0000-4000-8000-000000009761'), ('00000000-0000-4000-8000-000000009762');
insert into public.users(id) values ('00000000-0000-4000-8000-000000009761'), ('00000000-0000-4000-8000-000000009762') on conflict do nothing;
insert into public.workspaces(id,name,personal,creator_id) values ('00000000-0000-4000-8000-000000009763','Synthetic memory audit',false,'00000000-0000-4000-8000-000000009761');
insert into public.workspace_members(ws_id,user_id,type) values ('00000000-0000-4000-8000-000000009763','00000000-0000-4000-8000-000000009761','MEMBER') on conflict do nothing;
select lives_ok($$select private.record_ai_memory_audit('00000000-0000-4000-8000-000000009761','00000000-0000-4000-8000-000000009761','00000000-0000-4000-8000-000000009763','edit','mira','synthetic-memory','{"previousRevision":"old","revision":"new"}')$$, 'proper edit action succeeds');
select is((select count(*) from private.ai_memory_audit where ws_id='00000000-0000-4000-8000-000000009763' and action='edit'),1::bigint,'one proper edit audit row');
select is((select metadata from private.ai_memory_audit where ws_id='00000000-0000-4000-8000-000000009763' and action='edit'),'{"previousRevision":"old","revision":"new"}'::jsonb,'revision-only receipt metadata');
select lives_ok($$select private.record_ai_memory_audit('00000000-0000-4000-8000-000000009761','00000000-0000-4000-8000-000000009761','00000000-0000-4000-8000-000000009763',action) from unnest(array['backfill','delete','export','settings_update']) as actions(action)$$,'all prior actions still succeed');
select is((select count(*) from private.ai_memory_audit where ws_id='00000000-0000-4000-8000-000000009763'),5::bigint,'all prior audit actions retained');
select throws_ok($$select private.record_ai_memory_audit('00000000-0000-4000-8000-000000009761','00000000-0000-4000-8000-000000009761','00000000-0000-4000-8000-000000009763','unknown')$$,'23514',null,'unknown action remains rejected by real CHECK');
select throws_ok($$select private.record_ai_memory_audit('00000000-0000-4000-8000-000000009762','00000000-0000-4000-8000-000000009762','00000000-0000-4000-8000-000000009763','edit')$$,'42501','not_authorized','nonmember edit audit denied');
select ok((select relrowsecurity from pg_class where oid='private.ai_memory_audit'::regclass),'audit RLS remains enabled');
select ok(not has_table_privilege('authenticated','private.ai_memory_audit','INSERT'),'authenticated cannot bypass audit RPC');
select ok(not has_function_privilege('authenticated','private.record_ai_memory_audit(uuid,uuid,uuid,text,text,text,jsonb)','EXECUTE'),'authenticated cannot invoke service audit RPC');
select ok(not has_function_privilege('anon','private.record_ai_memory_audit(uuid,uuid,uuid,text,text,text,jsonb)','EXECUTE'),'anonymous cannot invoke service audit RPC');
select ok(has_function_privilege('service_role','private.record_ai_memory_audit(uuid,uuid,uuid,text,text,text,jsonb)','EXECUTE'),'service audit RPC remains available');
select * from finish();
rollback;
